<?php declare(strict_types=1); namespace App\Domain\NeedRequest; use App\Domain\Shared\Repository;
final class NeedRequestRepository extends Repository
{
    protected function table():string{return 'fiches_expression_besoin';}
    public function registry():array{return $this->database->query("SELECT feb.*,bc.numero_bc,bc.reference_client,bc.date_commande,c.nom_client,c.logo_client,d.numero_devis,d.total_ttc,o.num_offre,o.titre_offre,p.date_debut,p.date_fin,COALESCE(db.montant_fournitures,0) montant_fournitures,COALESCE(db.montant_transport,0) montant_transport,CONCAT_WS(' ',up.prenom,up.nom) prepared_name,CONCAT_WS(' ',ua.prenom,ua.nom) analyzed_name,CONCAT_WS(' ',uv.prenom,uv.nom) approved_name FROM fiches_expression_besoin feb JOIN bons_commande bc ON bc.id=feb.bon_commande_id JOIN devis d ON d.id=bc.devis_id LEFT JOIN client c ON c.id_client=bc.client_id LEFT JOIN offre o ON o.id_offre=d.offre_id LEFT JOIN debourses db ON db.bon_commande_id=bc.id LEFT JOIN planning_affaire p ON p.bon_commande_id=bc.id LEFT JOIN user_devis up ON up.id=feb.prepared_by LEFT JOIN user_devis ua ON ua.id=feb.analyzed_by LEFT JOIN user_devis uv ON uv.id=feb.approved_by WHERE d.archived_at IS NULL ORDER BY feb.created_at DESC,feb.id DESC")->fetchAll();}
    public function document(int $id):?array{$statement=$this->database->prepare("SELECT feb.*,bc.numero_bc,bc.reference_client,bc.date_commande,bc.date_reception,c.nom_client,c.code_client,d.numero_devis,d.total_ht,d.total_ttc,o.num_offre,o.titre_offre,p.libelle planning_label,p.date_debut,p.date_fin,db.id debourse_id,db.montant_fournitures,db.montant_transport,CONCAT_WS(' ',up.prenom,up.nom) prepared_name,up.fonction prepared_role,CONCAT_WS(' ',ua.prenom,ua.nom) analyzed_name,ua.fonction analyzed_role,CONCAT_WS(' ',uv.prenom,uv.nom) approved_name,uv.fonction approved_role FROM fiches_expression_besoin feb JOIN bons_commande bc ON bc.id=feb.bon_commande_id JOIN devis d ON d.id=bc.devis_id LEFT JOIN client c ON c.id_client=bc.client_id LEFT JOIN offre o ON o.id_offre=d.offre_id LEFT JOIN debourses db ON db.bon_commande_id=bc.id LEFT JOIN planning_affaire p ON p.bon_commande_id=bc.id LEFT JOIN user_devis up ON up.id=feb.prepared_by LEFT JOIN user_devis ua ON ua.id=feb.analyzed_by LEFT JOIN user_devis uv ON uv.id=feb.approved_by WHERE feb.id=:id");$statement->execute(['id'=>$id]);$document=$statement->fetch();if(!$document)return null;$lines=$this->database->prepare('SELECT * FROM debourse_lignes WHERE debourse_id=:id ORDER BY position,id');$lines->execute(['id'=>(int)$document['debourse_id']]);$document['lines']=$lines->fetchAll();return $document;}
    public function verify(int $id,string $uid):?array{$statement=$this->database->prepare('SELECT id,numero_feb,document_uid,document_version,statut,montant_demande,date_disponibilite,created_at FROM fiches_expression_besoin WHERE id=:id AND document_uid=:uid');$statement->execute(['id'=>$id,'uid'=>$uid]);return $statement->fetch()?:null;}
}
